package org.example
import org.logger.*
import org.parenthesesvalidator.ParenthesesValidator

class App {
    val greeting: String
        get() {
            return "Hello World!"
        }
}

fun main() {
    println(App().greeting)
    
    //val logger = Logger("logger")
    //logger.info("info message")
    //logger.warn("warning message")
    //logger.error("error message")
    
    
    println("Which option to test?")
    println("1. ()")
    println("2. )((())) ")
    println("3. )")
    println("4. (())((()())()) ")
    println("So you choose? dont forget change level for logging")
    var option1 = readLine()
    println("1. Trace")
    println("2. Info")
    println("3. Warn")
    println("4. Error")
    println("Your choice: ")
    var option2 = readLine()
    println("Format: ")
    var option3 = readLine()
    
    val logLevel = when(option2){
        "1" -> LogLevel.TRACE
        "2" -> LogLevel.INFO
        "3" -> LogLevel.WARN
        "4" -> LogLevel.ERROR
        else -> LogLevel.INFO
    }
    
    val parenthesesValidator = ParenthesesValidator(logLevel, option3 ?: "")
    
    val testString = when(option1){
        "1" -> "()"
        "2" -> ")((()))"
        "3" -> ")"
        "4" -> "(())((()())())"
        else -> ""
    }
    
    val isValid = parenthesesValidator.isValid(testString)
}
